import com.google.protobuf.gradle.*

plugins {
    application
    // Apply the application plugin to add support for building a CLI application in Java.
    alias(libs.plugins.javafx.plugin)
    jacoco
    alias(libs.plugins.protobuf)
}

repositories {
    // Use Maven Central for resolving dependencies.
    mavenCentral()
}

// Generated by https://www.lwjgl.org/customize
val lwjglNatives = Pair(
	System.getProperty("os.name")!!,
	System.getProperty("os.arch")!!
).let { (name, arch) ->
	when {
		"FreeBSD".equals(name)                                    ->
			"natives-freebsd"
		arrayOf("Linux", "SunOS", "Unit").any { name.startsWith(it) } ->
			if (arrayOf("arm", "aarch64").any { arch.startsWith(it) })
				"natives-linux${if (arch.contains("64") || arch.startsWith("armv8")) "-arm64" else "-arm32"}"
			else if (arch.startsWith("ppc"))
				"natives-linux-ppc64le"
			else if (arch.startsWith("riscv"))
				"natives-linux-riscv64"
			else
				"natives-linux"
		arrayOf("Mac OS X", "Darwin").any { name.startsWith(it) }     ->
			"natives-macos${if (arch.startsWith("aarch64")) "-arm64" else ""}"
		arrayOf("Windows").any { name.startsWith(it) }                ->
			if (arch.contains("64"))
				"natives-windows${if (arch.startsWith("aarch64")) "-arm64" else ""}"
			else
				"natives-windows-x86"
		else                                                                            ->
			throw Error("Unrecognized or unsupported platform. Please set \"lwjglNatives\" manually")
	}
}

dependencies {
    implementation(libs.javax.annotation)
    implementation(libs.guava)

    implementation(libs.joml)

    implementation(libs.tinylog.api)
    implementation(libs.tinylog.impl)

    implementation(platform(libs.lwjgl.bom))
    implementation(libs.lwjgl.lib)
    implementation(libs.lwjgl.opengl)
    implementation(libs.lwjgl.glfw)
    implementation(libs.lwjgl.tinyfd)
    testImplementation(libs.mockito.core)
    testImplementation(libs.mockito.junit.jupiter)
    runtimeOnly(variantOf(libs.lwjgl.lib) { classifier(lwjglNatives) })
    runtimeOnly(variantOf(libs.lwjgl.opengl) { classifier(lwjglNatives) })
    runtimeOnly(variantOf(libs.lwjgl.glfw) { classifier(lwjglNatives) })
    runtimeOnly(variantOf(libs.lwjgl.tinyfd) { classifier(lwjglNatives) })
    implementation(libs.onnxruntime)

    implementation(libs.protobuf.java)
    implementation(libs.grpc.stub)
    implementation(libs.grpc.protobuf)
    implementation(libs.grpc.okhttp)
}

testing {
    suites {
        // Configure the built-in test suite
        val test by getting(JvmTestSuite::class) {
            // Use JUnit Jupiter test framework
            useJUnitJupiter(libs.versions.junit)
        }
    }
}

jacoco {
    toolVersion = libs.versions.jacoco.get()
}

// Coverage report runs after tests
tasks.test {
    finalizedBy(tasks.jacocoTestReport)
}

tasks.jacocoTestReport {
    reports {
        html.required = true
    }
}

// Apply a specific Java toolchain to ease working on different environments.
java {
    toolchain {
        languageVersion = JavaLanguageVersion.of(libs.versions.java.get())
        // This is used in docker and CI CD as the default segfaults
        if (System.getenv("ENFORCE_VENDOR") == "1") {
            vendor = JvmVendorSpec.ORACLE
        }
    }
}

javafx {
    version = libs.versions.javafx.lib.get()
    modules("javafx.controls")
}

protobuf {
    protoc {
        artifact = libs.protoc.get().toString()
    }
    plugins {
	id("grpc") {
	    artifact = libs.grpc.gen.get().toString()
	}
    }
    generateProtoTasks {
	ofSourceSet("main").forEach {
	    it.plugins {
		id("grpc") { }
	    }
	}
    }
}

tasks.register<Exec>("pythonPrechecks") {
    // Set the working directory to the project root
    workingDir = project.rootDir

    val osName = System.getProperty("os.name").lowercase()
    val pythonExecutable = if (osName.contains("win")) "python" else "python3"

    // run python script
    commandLine(pythonExecutable, "app/src/main/resources/python/precheck.py")
}

tasks.named("run") {
    dependsOn("pythonPrechecks")
}

application {
    // Define the main class for the application.
    mainClass = "com.blackbox.app.App"
    applicationDefaultJvmArgs = run {
	val osName = System.getProperty("os.name")!!
	val macNames = arrayOf("Mac OS X", "Darwin")

	if (macNames.any {
	    osName.startsWith(it)
	})
	    listOf("-XstartOnFirstThread")
	else
	    listOf()
    }
}
